#include <stdio.h>
#include <string.h>

static void reverse(char *s, int i, int j)
{
    while (i < j) {
        char t = s[i];
        s[i] = s[j];
        s[j] = t;
        i++;
        j--;
    }
}

int main(void)
{
    char s[] = "one two three";
    int n = (int)strlen(s), i, start = 0;

    reverse(s, 0, n - 1);
    for (i = 0; i <= n; i++) {
        if (s[i] == ' ' || s[i] == '\0') {
            reverse(s, start, i - 1);
            start = i + 1;
        }
    }
    printf("%s\n", s);
    return 0;
}
```

